/**
 * Element Migration Functions
 *
 * Converts existing slide structure to canvas elements.
 * Provides backward compatibility while enabling new canvas-based editing.
 *
 * @module lib/canvas/element-migration
 */

/**
 * Generate stable ID for canvas element
 *
 * Generates a stable ID based on slide ID and element type prefix.
 * This ensures that the same element always gets the same ID across migrations,
 * enabling element tracking between DOM and Canvas modes.
 *
 * @param prefix - Element type prefix (e.g., 'headline', 'subtext')
 * @param slideId - The slide ID to ensure uniqueness across slides
 * @returns Stable element ID in format: {slideId}-{prefix}
 */
function generateId(prefix: string, slideId: string): string {
  return `${slideId}-${prefix}`;
}
import { Slide, SlideContent } from '@/types/slide';
import { getContentValue, getContentPosition, hasPositionConfig, getContentStyle, ImageConfig, ContentStyle } from '@/types/slide-subtypes';
import { CanvasElement, TextElementData, ImageElementData, BackgroundElementData, DecoratorElementData, DecoratorType, CTAElementData } from '@/types/canvas-elements';
import { DecoratorConfig } from '@/types/decorators';

// Constants
const SLIDE_WIDTH = 1080;
const SLIDE_HEIGHT = 1350;

// Migration cache for performance optimization
// Cache key: stringified slide data
// Cache value: computed CanvasElement array
const migrationCache = new Map<string, CanvasElement[]>();

/**
 * Generate cache key for migration
 *
 * Creates a unique cache key based on slide data that affects migration result.
 *
 * @param slide - The slide to cache
 * @param theme - Pillar theme configuration
 * @param styleTemplate - Style template configuration
 * @param subTypeConfig - Sub-type configuration
 * @param decoratorConfig - Decorator configuration
 * @returns Cache key string
 */
function generateCacheKey(
  slide: Slide,
  theme: any,
  styleTemplate: any,
  subTypeConfig: any,
  decoratorConfig: any
): string {
  // Only include properties that affect migration result
  const cacheData = {
    slideId: slide.id,
    content: slide.content,
    style: slide.style,
    pillar: slide.pillar,
    themeId: theme?.id,
    templateId: styleTemplate?.id,
  };

  return JSON.stringify(cacheData);
}

/**
 * Clear migration cache
 *
 * Clears the migration cache. Call this when:
 * - Theme configuration changes
 * - Style template configuration changes
 * - After bulk slide updates
 *
 * @param slideId - Optional slide ID to clear cache for specific slide only
 */
export function clearMigrationCache(slideId?: string): void {
  if (slideId) {
    // Clear cache for specific slide
    for (const [key] of migrationCache) {
      if (key.startsWith(`{"slideId":"${slideId}"`)) {
        migrationCache.delete(key);
      }
    }
  } else {
    // Clear entire cache
    migrationCache.clear();
  }
}

/**
 * Get migration cache statistics
 *
 * Returns statistics about the migration cache for monitoring and debugging.
 *
 * @returns Cache statistics object
 */
export function getMigrationCacheStats(): {
  size: number;
  keys: string[];
  memoryUsageKB: number;
} {
  let totalSize = 0;
  const keys: string[] = [];

  for (const [key, value] of migrationCache) {
    keys.push(key);
    totalSize += key.length + JSON.stringify(value).length;
  }

  return {
    size: migrationCache.size,
    keys,
    memoryUsageKB: Math.round(totalSize / 1024),
  };
}

/**
 * Migrate headline from slide to canvas element
 *
 * Converts slide.content.headline to a TextElement.
 * Preserves positioning and styling.
 * Respects useTheme flag (Phase 1): if useTheme is true, uses theme styling; if false, uses style overrides.
 *
 * @param slide - The slide to migrate headline from
 * @param theme - Pillar theme configuration (optional, for useTheme: true)
 * @returns CanvasElement for the headline, or null if no headline exists
 */
export function migrateHeadline(slide: Slide, theme?: any): CanvasElement | null {
  const headlineContent = slide.content.headline;

  if (!headlineContent) {
    return null;
  }

  // Get headline value (handle both string and PositionedContent)
  const headlineValue = typeof headlineContent === 'string'
    ? headlineContent
    : headlineContent.value;

  if (!headlineValue) {
    return null;
  }

  // Get position configuration
  const position = typeof headlineContent === 'object' && headlineContent.position
    ? headlineContent.position
    : undefined;

  // Get style configuration (Phase 1)
  const styleConfig = typeof headlineContent === 'object' && headlineContent.style
    ? headlineContent.style
    : undefined;

  // Calculate element position and size
  const { x, y, width, height, zIndex, alignment } = calculateElementPosition(
    position,
    'headline',
    headlineValue
  );

  // Get styling - respect useTheme flag (Phase 1)
  const styling = getElementStyling(slide, 'headline', styleConfig, theme);

  // Create TextElement
  const textElement: CanvasElement = {
    id: generateId('headline', slide.id),
    type: 'text',
    name: 'Headline',
    x,
    y,
    width,
    height,
    rotation: position?.rotation || 0,
    scaleX: 1,
    scaleY: 1,
    opacity: position?.opacity ?? 1,
    visible: true,
    locked: false,
    zIndex,
    data: {
      content: headlineValue,
      fontSize: styling.fontSize,
      fontFamily: styling.fontFamily,
      fontWeight: styling.fontWeight,
      color: styling.color,
      alignment: alignment as 'left' | 'center' | 'right',
      lineHeight: styling.lineHeight,
      letterSpacing: styling.letterSpacing,
      textDecoration: styling.textDecoration || 'none',
      fontStyle: styling.fontStyle || 'normal',
      _useTheme: styleConfig?.useTheme ?? true, // Phase 1: Tag element with useTheme flag
    } as TextElementData & { _useTheme?: boolean },
  };

  return textElement;
}

