/**
 * Migrate bullets from slide to canvas element
 *
 * Converts slide.content.bullets to a TextElement.
 * Adds bullet point rendering, supports dynamic bullet list.
 * Respects useTheme flag (Phase 1).
 *
 * @param slide - The slide to migrate bullets from
 * @param theme - Pillar theme configuration (optional, for useTheme: true)
 * @returns CanvasElement for the bullets, or null if no bullets exist
 */
export function migrateBullets(slide: Slide, theme?: any): CanvasElement | null {
  const bulletsContent = slide.content.bullets;

  if (!bulletsContent) {
    return null;
  }

  // Get bullets value (handle both array and PositionedContent)
  const bulletsValue = Array.isArray(bulletsContent)
    ? bulletsContent
    : bulletsContent.value;

  if (!bulletsValue || bulletsValue.length === 0) {
    return null;
  }

  // Format bullets with bullet points
  const formattedBullets = bulletsValue.map((bullet, index) => {
    // Check if it already starts with a bullet point
    if (bullet.startsWith('•') || bullet.startsWith('-') || bullet.startsWith('*')) {
      return bullet;
    }
    // Add bullet point if not present
    return `• ${bullet}`;
  }).join('\n');

  // Get position configuration
  const position = hasPositionConfig(bulletsContent) ? bulletsContent.position : undefined;

  // Get style configuration (Phase 1)
  const styleConfig = typeof bulletsContent === 'object' && bulletsContent.style
    ? bulletsContent.style
    : undefined;

  // Calculate element position and size
  const { x, y, width, height, zIndex, alignment } = calculateElementPosition(
    position,
    'bullets',
    formattedBullets
  );

  // Get styling - respect useTheme flag (Phase 1)
  const styling = getElementStyling(slide, 'bullets', styleConfig, theme);

  // Create TextElement
  const textElement: CanvasElement = {
    id: generateId('bullets', slide.id),
    type: 'text',
    name: 'Bullets',
    x,
    y,
    width,
    height,
    rotation: position?.rotation || 0,
    scaleX: 1,
    scaleY: 1,
    opacity: position?.opacity ?? 1,
    visible: true,
    locked: false,
    zIndex,
    data: {
      content: formattedBullets,
      fontSize: styling.fontSize,
      fontFamily: styling.fontFamily,
      fontWeight: styling.fontWeight,
      color: styling.color,
      alignment: alignment as 'left' | 'center' | 'right',
      lineHeight: styling.lineHeight,
      letterSpacing: styling.letterSpacing,
      textDecoration: styling.textDecoration || 'none',
      fontStyle: styling.fontStyle || 'normal',
      _useTheme: styleConfig?.useTheme ?? true, // Phase 1: Tag element with useTheme flag
    } as TextElementData & { _useTheme?: boolean },
  };

  return textElement;
}

/**
 * Migrate quote from slide to canvas element
 *
 * Converts slide.content.quote to a TextElement.
 * Adds quote styling and quote marks.
 * Respects useTheme flag (Phase 1).
 *
 * @param slide - The slide to migrate quote from
 * @param theme - Pillar theme configuration (optional, for useTheme: true)
 * @returns CanvasElement for the quote, or null if no quote exists
 */
export function migrateQuote(slide: Slide, theme?: any): CanvasElement | null {
  const quoteContent = slide.content.quote;

  if (!quoteContent) {
    return null;
  }

  // Get quote value
  const quoteValue = typeof quoteContent === 'string'
    ? quoteContent
    : quoteContent.value;

  if (!quoteValue) {
    return null;
  }

  // Add quote marks if not present
  const formattedQuote = quoteValue.startsWith('"')
    ? quoteValue
    : `"${quoteValue}"`;

  // Get position configuration
  const position = typeof quoteContent === 'object' && quoteContent.position
    ? quoteContent.position
    : undefined;

  // Get style configuration (Phase 1)
  const styleConfig = typeof quoteContent === 'object' && quoteContent.style
    ? quoteContent.style
    : undefined;

  // Calculate element position and size
  const { x, y, width, height, zIndex, alignment } = calculateElementPosition(
    position,
    'quote',
    formattedQuote
  );

  // Get styling - respect useTheme flag (Phase 1)
  const styling = getElementStyling(slide, 'quote', styleConfig, theme);

  // Create TextElement with italic font style (default for quotes)
  const textElement: CanvasElement = {
    id: generateId('quote', slide.id),
    type: 'text',
    name: 'Quote',
    x,
    y,
    width,
    height,
    rotation: position?.rotation || 0,
    scaleX: 1,
    scaleY: 1,
    opacity: position?.opacity ?? 1,
    visible: true,
    locked: false,
    zIndex,
    data: {
      content: formattedQuote,
      fontSize: styling.fontSize,
      fontFamily: styling.fontFamily,
      fontWeight: styling.fontWeight,
      color: styling.color,
      alignment: alignment as 'left' | 'center' | 'right',
      lineHeight: styling.lineHeight,
      letterSpacing: styling.letterSpacing,
      textDecoration: styling.textDecoration || 'none',
      fontStyle: styling.fontStyle || 'italic', // Quotes are typically italic
      _useTheme: styleConfig?.useTheme ?? true, // Phase 1: Tag element with useTheme flag
    } as TextElementData & { _useTheme?: boolean },
  };

  return textElement;
}

