import { toPng, toJpeg } from 'html-to-image';
import { ExportSettings } from '@/types/index';

export interface ExportResult {
  dataUrl: string;
  filename: string;
}

export async function exportSlideAsPng(
  element: HTMLElement,
  filename: string,
  settings: ExportSettings
): Promise<ExportResult> {
  const options = {
    pixelRatio: settings.pixelRatio,
    quality: settings.quality,
    cacheBust: true,
    style: {
      transform: 'scale(1)',
      transformOrigin: 'top left',
    },
  };

  let dataUrl: string;

  if (settings.format === 'jpeg') {
    dataUrl = await toJpeg(element, {
      ...options,
      backgroundColor: '#000000',
    });
  } else {
    dataUrl = await toPng(element, options);
  }

  return {
    dataUrl,
    filename: `${filename}.${settings.format}`,
  };
}

export async function exportAllSlides(
  elements: HTMLElement[],
  baseName: string,
  settings: ExportSettings,
  onProgress?: (current: number, total: number) => void
): Promise<ExportResult[]> {
  const results: ExportResult[] = [];

  for (let i = 0; i < elements.length; i++) {
    const element = elements[i];
    const filename = `${baseName}_${String(i + 1).padStart(2, '0')}`;

    onProgress?.(i + 1, elements.length);

    const result = await exportSlideAsPng(element, filename, settings);
    results.push(result);
  }

  return results;
}

export function downloadDataUrl(dataUrl: string, filename: string): void {
  const link = document.createElement('a');
  link.download = filename;
  link.href = dataUrl;
  link.click();
}
