/**
 * Unified Decorator Configuration Types
 *
 * This file defines the single source of truth for all decorator configurations.
 * It replaces the three competing systems:
 * 1. Inline constants in ThemedSlide.tsx
 * 2. Style template decorators in styles/index.ts
 * 3. Decorator config in decorators/index.ts
 *
 * Configuration Hierarchy (from lowest to highest priority):
 * - Carousel config (base settings)
 * - Pillar config (override carousel)
 * - Slide config (override pillar)
 * - Style template (suggestion, not override)
 */

/**
 * Slide number style options
 */
export type SlideNumberStyle =
  | 'decimal'      // 1, 2, 3...
  | 'roman'        // I, II, III...
  | 'circle'       // ①, ②, ③...
  | 'square'       // ⓵, ⓶, ⓷...
  | 'minimal'      // Small, unstyled numbers
  | 'pillar-branded'; // Custom pillar-styled numbers

/**
 * Slide number position options
 */
export type SlideNumberPosition =
  | 'top-left'
  | 'top-right'
  | 'bottom-left'
  | 'bottom-right';

/**
 * Border style options
 */
export type BorderStyle =
  | 'solid'        // ───────
  | 'dashed'       // - - - -
  | 'dotted'       // . . . .
  | 'double'       // ═══════
  | 'gradient';    // Gradient border

/**
 * Border position options
 */
export type BorderPosition =
  | 'full'         // All sides
  | 'top'
  | 'bottom'
  | 'left'
  | 'right'
  | 'corners'      // Only corner accents
  | 'top-bottom'
  | 'left-right';

/**
 * Frame style options
 */
export type FrameStyle =
  | 'photo'        // Photo frame with corners
  | 'film'         // Film strip frame
  | 'tech'         // Tech/bracket frame
  | 'minimal'      // Simple frame
  | 'none';        // No frame

/**
 * Accent line position options
 */
export type AccentLinePosition =
  | 'top'
  | 'bottom'
  | 'left'
  | 'right'
  | 'both'
  | 'none';

/**
 * Corner accent style
 */
export interface CornerAccent {
  enabled: boolean;
  style: 'bracket' | 'line' | 'dot' | 'triangle' | 'circle' | 'cross' | 'star' | 'diamond' | 'arrow' | 'wave';
  symbolId?: string; // New: Reference to symbol from corner-symbols.ts
  size: number;
  color?: string;
  secondaryColor?: string; // For dual-color effects
  thickness?: number; // For line-based styles
  rotation?: number; // Rotation angle
  offset?: { x: number; y: number }; // Position offset
  effects?: {
    shadow?: boolean;
    glow?: boolean;
    blur?: boolean;
  };
}

/**
 * Border configuration
 */
export interface BorderConfig {
  enabled: boolean;
  style: BorderStyle;
  thickness: number;
  position: BorderPosition;
  color?: string;
  offset?: number;
  padding?: number;
  cornerRadius?: number;
}

/**
 * Slide number configuration
 */
export interface SlideNumberConfig {
  enabled: boolean;
  style: SlideNumberStyle;
  position: SlideNumberPosition;
  font?: string;
  size?: number;
  color?: string;
  showBackground?: boolean;
}

/**
 * Hashtag configuration
 */
export interface HashtagConfig {
  enabled: boolean;
  text?: string;
  position: SlideNumberPosition;
  size?: number;
  color?: string;
  showBackground?: boolean;
}

/**
 * Watermark configuration
 */
export interface WatermarkConfig {
  enabled: boolean;
  text?: string;
  x: number; // 0-100 (percentage from left)
  y: number; // 0-100 (percentage from top)
  opacity?: number;
  size?: number;
  rotation?: number;
  zIndex?: number; // Ensure proper layering
}

/**
 * Logo configuration
 */
export interface LogoConfig {
  enabled: boolean;
  position: SlideNumberPosition;
  size: number;
  opacity: number;
  imageUrl?: string;
  blendMode?: 'normal' | 'multiply' | 'screen' | 'overlay' | 'darken' | 'lighten' | 'color-dodge' | 'color-burn' | 'hard-light' | 'soft-light' | 'difference' | 'exclusion' | 'hue' | 'saturation' | 'color' | 'luminosity';
}

/**
 * Frame configuration
 */
export interface FrameConfig {
  enabled: boolean;
  style: FrameStyle;
  thickness?: number;
  color?: string;
  innerPadding?: number;
}

/**
 * Accent line configuration
 */
export interface AccentLineConfig {
  enabled: boolean;
  // Multi-select positions with independent controls
  positions: {
    top?: {
      enabled: boolean;
      offset: number; // Distance from top edge in pixels
      thickness: number;
      length: number; // Percentage of width
      color?: string;
      gradient?: boolean;
    };
    bottom?: {
      enabled: boolean;
      offset: number;
      thickness: number;
      length: number;
      color?: string;
      gradient?: boolean;
    };
    left?: {
      enabled: boolean;
      offset: number;
      thickness: number;
      length: number; // Percentage of height
      color?: string;
      gradient?: boolean;
    };
    right?: {
      enabled: boolean;
      offset: number;
      thickness: number;
      length: number;
      color?: string;
      gradient?: boolean;
    };
  };
}

/**
 * Unified Decorator Configuration
 *
 * This is the single source of truth for all decorator settings.
 * It combines all decorator options from the three old systems.
 */
export interface DecoratorConfig {
  // Slide Numbers
  slideNumber: SlideNumberConfig;

  // Border
  border: BorderConfig;

  // Hashtag
  hashtag: HashtagConfig;

  // Watermark
  watermark: WatermarkConfig;

  // Logo
  logo: LogoConfig;

  // Frame
  frame: FrameConfig;

  // Corner Accents
  cornerAccents: {
    enabled: boolean;
    topLeft?: CornerAccent;
    topRight?: CornerAccent;
    bottomLeft?: CornerAccent;
    bottomRight?: CornerAccent;
  };

  // Accent Lines
  accentLines: AccentLineConfig;

  // Background Effects
  backgroundEffects: {
    shadow?: boolean;
    glow?: boolean;
    blur?: boolean;
    noise?: boolean;
  };

  // Pillar Label
  pillarLabel: {
    enabled: boolean;
    position: SlideNumberPosition;
    size?: number;
  };
}

