/**
 * Merge decorator configurations with proper precedence
 *
 * @param base - Base configuration (usually carousel level)
 * @param override - Override configuration (pillar, slide, or template level)
 * @returns Merged configuration
 */
export function mergeDecoratorConfig(
  base: DecoratorConfig,
  override: Partial<DecoratorConfig>
): DecoratorConfig {
  return {
    slideNumber: { ...base.slideNumber, ...override.slideNumber },
    border: { ...base.border, ...override.border },
    hashtag: { ...base.hashtag, ...override.hashtag },
    watermark: { ...base.watermark, ...override.watermark },
    logo: { ...base.logo, ...override.logo, imageUrl: override.logo?.imageUrl || base.logo.imageUrl || '/default-logo.png', blendMode: override.logo?.blendMode || base.logo.blendMode },
    frame: { ...base.frame, ...override.frame },
    cornerAccents: {
      ...base.cornerAccents,
      ...override.cornerAccents,
      topLeft: override.cornerAccents?.topLeft
        ? { ...base.cornerAccents.topLeft, ...override.cornerAccents.topLeft }
        : base.cornerAccents.topLeft,
      topRight: override.cornerAccents?.topRight
        ? { ...base.cornerAccents.topRight, ...override.cornerAccents.topRight }
        : base.cornerAccents.topRight,
      bottomLeft: override.cornerAccents?.bottomLeft
        ? { ...base.cornerAccents.bottomLeft, ...override.cornerAccents.bottomLeft }
        : base.cornerAccents.bottomLeft,
      bottomRight: override.cornerAccents?.bottomRight
        ? { ...base.cornerAccents.bottomRight, ...override.cornerAccents.bottomRight }
        : base.cornerAccents.bottomRight,
    },
    accentLines: { ...base.accentLines, ...override.accentLines },
    backgroundEffects: { ...base.backgroundEffects, ...override.backgroundEffects },
    pillarLabel: { ...base.pillarLabel, ...override.pillarLabel },
  };
}